def ordinalLiftDerivative (f : X → Y) (A : Set X) : Set X :=
  {x | x ∈ A ∧ ∀ U : Set X, IsOpen U → x ∈ U →
    ∃ z ∈ A, z ∈ U ∧ f z ≠ f x}

